          "tests": "for _ in range(60):\n    p = generate_password(10, True, True, True, True)\n    assert len(p) == 10, \"Длина должна быть 10, получено \" + str(len(p))\n    assert any(c in LOWER for c in p), \"Нет строчной буквы в \" + p\n    assert any(c in UPPER for c in p), \"Нет заглавной буквы в \" + p\n    assert any(c in DIGITS for c in p), \"Нет цифры в \" + p\n    assert any(c in SYMBOLS for c in p), \"Нет символа в \" + p\nonly_digits = generate_password(8, False, False, True, False)\nassert only_digits.isdigit() and len(only_digits) == 8, \"Только цифры: 8 цифр\"\nassert generate_password(4, True, True, True, True) != generate_password(4, True, True, True, True) or True, \"ok\"\nassert len(set(generate_password(20) for _ in range(30))) > 25, \"Пароли должны быть разными\"\ntry:\n    generate_password(5, False, False, False, False)\n    assert False, \"Без групп должен быть ValueError\"\nexcept ValueError:\n    pass\ntry:\n    generate_password(2, True, True, True, True)\n    assert False, \"Длина 2 при 4 группах — ValueError\"\nexcept ValueError:\n    pass\n",
          "solution": "import string\nimport secrets\n\nLOWER = string.ascii_lowercase\nUPPER = string.ascii_uppercase\nDIGITS = string.digits\nSYMBOLS = string.punctuation\n\ndef build_alphabet(lower=True, upper=True, digits=True, symbols=False):\n    alphabet = \"\"\n    if lower:\n        alphabet += LOWER\n    if upper:\n        alphabet += UPPER\n    if digits:\n        alphabet += DIGITS\n    if symbols:\n        alphabet += SYMBOLS\n    return alphabet\n\ndef generate_password(length=12, lower=True, upper=True, digits=True, symbols=False):\n    groups = []\n    if lower:\n        groups.append(LOWER)\n    if upper:\n        groups.append(UPPER)\n    if digits:\n        groups.append(DIGITS)\n    if symbols:\n        groups.append(SYMBOLS)\n    if len(groups) == 0:\n        raise ValueError(\"choose at least one group\")\n    if length < len(groups):\n        raise ValueError(\"length is too small\")\n    alphabet = \"\".join(groups)\n    chars = []\n    for g in groups:\n        chars.append(secrets.choice(g))\n    while len(chars) < length:\n        chars.append(secrets.choice(alphabet))\n    secrets.SystemRandom().shuffle(chars)\n    return \"\".join(chars)\n",
