          "starter": "import math\nimport string\n\nLOWER = string.ascii_lowercase\nUPPER = string.ascii_uppercase\nDIGITS = string.digits\nSYMBOLS = string.punctuation\n\ndef pool_size(password):\n    # твой код здесь\n    pass\n\ndef entropy_bits(password):\n    # твой код здесь\n    pass\n",
          "tests": "assert pool_size(\"abc\") == 26, \"Только строчные: 26\"\nassert pool_size(\"Ab1\") == 62, \"Строчные + заглавные + цифры: 62\"\nassert pool_size(\"a!\") == 26 + 32, \"Строчные + символы: 58\"\nassert pool_size(\"12345\") == 10, \"Только цифры: 10\"\nassert pool_size(\"\") == 0, \"Пустой пароль: 0\"\nassert abs(entropy_bits(\"Ab1\") - 3 * math.log2(62)) < 1e-9, \"entropy_bits('Ab1') = 3·log2(62)\"\nassert abs(entropy_bits(\"abcdefgh\") - 8 * math.log2(26)) < 1e-9, \"8 строчных: 8·log2(26)\"\nassert entropy_bits(\"\") == 0, \"Пустой пароль — энтропия 0\"\nassert entropy_bits(\"aaaaaaaaaaaa\") == 12 * math.log2(26), \"Длина считается по символам (простая модель)\"\n",
          "solution": "import math\nimport string\n\nLOWER = string.ascii_lowercase\nUPPER = string.ascii_uppercase\nDIGITS = string.digits\nSYMBOLS = string.punctuation\n\ndef pool_size(password):\n    size = 0\n    if any(c in LOWER for c in password):\n        size += len(LOWER)\n    if any(c in UPPER for c in password):\n        size += len(UPPER)\n    if any(c in DIGITS for c in password):\n        size += len(DIGITS)\n    if any(c in SYMBOLS for c in password):\n        size += len(SYMBOLS)\n    return size\n\ndef entropy_bits(password):\n    if password == \"\":\n        return 0\n    return len(password) * math.log2(pool_size(password))\n",
