          "tests": "assert crack_seconds(10, 1) == 512, \"2**10 / 2 / 1 = 512\"\nassert crack_seconds(0, 1) == 0.5, \"2**0 / 2 = 0.5\"\nassert crack_seconds(34, 1e9) == 2 ** 34 / 2 / 1e9, \"Формула должна совпадать\"\nassert human_time(30) == (30.0, \"seconds\"), \"30 секунд\"\nassert human_time(120) == (2.0, \"minutes\"), \"120 секунд = 2 минуты\"\nassert human_time(7200) == (2.0, \"hours\"), \"7200 секунд = 2 часа\"\nassert human_time(86400 * 3) == (3.0, \"days\"), \"3 суток\"\nassert human_time(31536000 * 5) == (5.0, \"years\"), \"5 лет\"\nassert human_time(0.25) == (0.2, \"seconds\") or human_time(0.25) == (0.3, \"seconds\"), \"Меньше секунды — секунды\"\nassert human_time(31536000 * 1000000) == (1000000.0, \"years\"), \"Миллион лет\"\n",
