          "code": "\"\"\"Генератор паролей и проверка надёжности.\"\"\"\nimport math\nimport secrets\nimport string\n\nLOWER = string.ascii_lowercase\nUPPER = string.ascii_uppercase\nDIGITS = string.digits\nSYMBOLS = string.punctuation\n\nCOMMON = {\"123456\", \"password\", \"qwerty\", \"12345678\", \"111111\", \"admin\", \"letmein\", \"iloveyou\"}\n\n\ndef build_alphabet(lower=True, upper=True, digits=True, symbols=False):\n    alphabet = \"\"\n    if lower:\n        alphabet += LOWER\n    if upper:\n        alphabet += UPPER\n    if digits:\n        alphabet += DIGITS\n    if symbols:\n        alphabet += SYMBOLS\n    return alphabet\n\n\ndef generate_password(length=12, lower=True, upper=True, digits=True, symbols=False):\n    groups = []\n    if lower:\n        groups.append(LOWER)\n    if upper:\n        groups.append(UPPER)\n    if digits:\n        groups.append(DIGITS)\n    if symbols:\n        groups.append(SYMBOLS)\n    if not groups:\n        raise ValueError(\"choose at least one character group\")\n    if length < len(groups):\n        raise ValueError(\"length is too small for chosen groups\")\n    alphabet = \"\".join(groups)\n    chars = [secrets.choice(g) for g in groups]\n    while len(chars) < length:\n        chars.append(secrets.choice(alphabet))\n    secrets.SystemRandom().shuffle(chars)\n    return \"\".join(chars)\n\n\ndef pool_size(password):\n    size = 0\n    if any(c in LOWER for c in password):\n        size += len(LOWER)\n    if any(c in UPPER for c in password):\n        size += len(UPPER)\n    if any(c in DIGITS for c in password):\n        size += len(DIGITS)\n    if any(c in SYMBOLS for c in password):\n        size += len(SYMBOLS)\n    if any(c not in LOWER + UPPER + DIGITS + SYMBOLS for c in password):\n        size += 32\n    return size\n\n\ndef entropy_bits(password):\n    if password == \"\":\n        return 0.0\n    return len(password) * math.log2(pool_size(password))\n\n\ndef strength(password, common=COMMON):\n    if password.lower() in common:\n        return \"weak\"\n    bits = entropy_bits(password)\n    if bits < 40:\n        return \"weak\"\n    if bits < 60:\n        return \"medium\"\n    return \"strong\"\n\n\ndef crack_seconds(bits, guesses_per_second=1e10):\n    return 2 ** bits / 2 / guesses_per_second\n\n\ndef human_time(seconds):\n    units = [(\"лет\", 365 * 24 * 3600), (\"дней\", 24 * 3600), (\"часов\", 3600), (\"минут\", 60)]\n    if seconds < 1:\n        return \"меньше секунды\"\n    for name, size in units:\n        if seconds >= size:\n            return f\"{seconds / size:.1f} {name}\"\n    return f\"{seconds:.0f} секунд\"\n\n\ndef ask_int(prompt, low, high):\n    while True:\n        try:\n            n = int(input(prompt))\n        except ValueError:\n            print(\"Нужно целое число.\")\n            continue\n        if low <= n <= high:\n            return n\n        print(f\"Число должно быть от {low} до {high}.\")\n\n\ndef ask_yes(prompt):\n    return input(prompt + \" (y/n): \").strip().lower() == \"y\"\n\n\ndef main():\n    print(\"1 - сгенерировать пароль\")\n    print(\"2 - проверить свой пароль\")\n    choice = ask_int(\"Выбор: \", 1, 2)\n    if choice == 1:\n        length = ask_int(\"Длина (8-64): \", 8, 64)\n        symbols = ask_yes(\"Добавить символы?\")\n        pwd = generate_password(length, symbols=symbols)\n        print(\"Пароль:\", pwd)\n    else:\n        pwd = input(\"Пароль для проверки: \")\n    bits = entropy_bits(pwd)\n    print(\"Энтропия:\", round(bits, 1), \"бит\")\n    print(\"Оценка:\", strength(pwd))\n    print(\"Перебор займёт примерно:\", human_time(crack_seconds(bits)))\n\n\nif __name__ == \"__main__\":\n    main()"
